-- Replace shared tier artwork with 22 individual images and material animations.
-- Visual fields only. No rewards, fees, ranks, balances, item IDs, owners or
-- frozen bonus values are changed. Preserve administrator-supplied artwork.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('topfragg-competition-rewards'));
CREATE TEMP TABLE first_drop_art_v2 (
 id TEXT PRIMARY KEY, old_url TEXT NOT NULL, image_url TEXT NOT NULL,
 poster_url TEXT NOT NULL, animation_type TEXT NOT NULL,
 old_description TEXT NOT NULL, description TEXT NOT NULL
) ON COMMIT DROP;
