UPDATE "MarketplaceItem" i SET metadata = i.metadata || jsonb_build_object(
 'image_url', a.image_url, 'poster_url', a.poster_url,
 'animation_type', a.animation_type, 'artwork_version', 2
) || CASE WHEN i.metadata->>'description' = a.old_description
 THEN jsonb_build_object('description', a.description) ELSE '{}'::jsonb END,
 updated_date = CURRENT_TIMESTAMP
FROM first_drop_art_v2 a
WHERE i.id = a.id AND i.metadata->>'image_url' = a.old_url
 AND i.metadata->>'collection_key' = 'first_drop_2026';

UPDATE "UserInventory" i SET metadata = i.metadata || jsonb_build_object(
 'item_image', a.image_url, 'artwork_version', 2
) || CASE WHEN i.metadata->>'item_description' = a.old_description
 THEN jsonb_build_object('item_description', a.description) ELSE '{}'::jsonb END,
 updated_date = CURRENT_TIMESTAMP
FROM first_drop_art_v2 a
WHERE i.metadata->>'item_id' = a.id AND i.metadata->>'item_image' = a.old_url;

UPDATE "CompetitionRewardGrant" g SET metadata = jsonb_set(g.metadata, '{item}',
 (g.metadata->'item') || jsonb_build_object(
  'image_url', a.image_url, 'poster_url', a.poster_url, 'artwork_version', 2
 ) || CASE WHEN g.metadata->'item'->>'description' = a.old_description
 THEN jsonb_build_object('description', a.description) ELSE '{}'::jsonb END
)
FROM first_drop_art_v2 a
WHERE g.metadata->>'kind' = 'item' AND g.metadata->'item'->>'id' = a.id
 AND g.metadata->'item'->>'image_url' = a.old_url;
COMMIT;
